// Dart Sound Null Safety Examples

void main() {
  // === Basic Null Safety ===

  // Non-nullable - must be initialized
  String name = "Alice";
  // String name; // ❌ Error: must be initialized

  // Nullable - can be null
  String? nickname; // OK, defaults to null
  String? email = null; // Explicitly null

  print('Name: $name');
  print('Nickname: $nickname'); // prints: null

  // === Working with nullable types ===

  // Null check before use
  if (nickname != null) {
    print('Nickname length: ${nickname.length}'); // Smart cast to non-null
  }

  // Null-aware operators
  print('Email length: ${email?.length}'); // null if email is null
  print('Display name: ${nickname ?? name}'); // Use name if nickname is null

  // === Late keyword examples ===
  print('\n--- Late Keyword Examples ---');

  // Example 1: Late initialization
  LateInitializationExample example1 = LateInitializationExample();
  example1.setup();
  example1.printInfo();

  // Example 2: Expensive computation
  ExpensiveComputationExample example2 = ExpensiveComputationExample();
  print('First access: ${example2.expensiveValue}');
  print('Second access: ${example2.expensiveValue}'); // Uses cached value

  // Example 3: Circular dependencies
  CircularDependencyExample();
}

// === Late Keyword Use Cases ===

// Use Case 1: Late initialization (when you know it will be set before use)
class LateInitializationExample {
  late String databaseConnection; // Will be set in setup()
  late int userId; // Will be set in setup()

  void setup() {
    // Simulate initialization that happens after constructor
    databaseConnection = "postgresql://localhost:5432/mydb";
    userId = 12345;
  }

  void printInfo() {
    // Safe to use because we know setup() was called
    print('Database: $databaseConnection');
    print('User ID: $userId');
  }
}

// Use Case 2: Lazy initialization for expensive computations
class ExpensiveComputationExample {
  late String expensiveValue = _computeExpensiveValue();

  String _computeExpensiveValue() {
    print('Computing expensive value...');
    // Simulate expensive computation
    return 'Computed result: ${DateTime.now().millisecondsSinceEpoch}';
  }
}

// Use Case 3: Circular dependencies
class CircularDependencyExample {
  late Person person1;
  late Person person2;

  CircularDependencyExample() {
    person1 = Person('Alice');
    person2 = Person('Bob');

    // Create circular reference
    person1.friend = person2;
    person2.friend = person1;

    print('${person1.name} is friends with ${person1.friend!.name}');
    print('${person2.name} is friends with ${person2.friend!.name}');
  }
}

class Person {
  final String name;
  Person? friend; // Could use late here too if we guarantee it's always set

  Person(this.name);
}

// === Comparison: late vs nullable ===

class ConfigManager {
  // Use late when: You guarantee initialization before first use
  late String apiKey; // Will be loaded from config file
  late String databaseUrl; // Will be loaded from environment

  // Use nullable when: The value might legitimately be absent
  String? userPreference; // User might not have set this
  String? cacheDirectory; // Might not be available on all platforms

  void loadConfig() {
    apiKey = 'abc123'; // Must set this
    databaseUrl = 'localhost:5432'; // Must set this
    // userPreference and cacheDirectory can remain null
  }

  void demonstrateUsage() {
    // late variables - use directly (but ensure they're initialized)
    print('API Key: $apiKey');
    print('Database: $databaseUrl');

    // nullable variables - need null checks
    if (userPreference != null) {
      print('User preference: $userPreference');
    } else {
      print('No user preference set');
    }

    final cache = cacheDirectory ?? '/tmp/default_cache';
    print('Cache directory: $cache');
  }
}

