  print('=== Null Safety Error Prevention ===');

  // Demonstrating safe practices
  SafePracticesExample example = SafePracticesExample();
  example.demonstrateSafePractices();

  print('\n=== Late vs Nullable Decision Guide ===');
  DecisionGuideExample guide = DecisionGuideExample();
  guide.demonstrate();
}

class SafePracticesExample {
  String? nullableValue;
  late String lateValue;
  bool isInitialized = false;

  void demonstrateSafePractices() {
    // ✅ Safe ways to work with nullable values
    print('1. Null-aware access:');
    print('   Length: ${nullableValue?.length ?? 0}');

    print('2. Null check with smart cast:');
    if (nullableValue != null) {
      // nullableValue is automatically cast to non-null String here
      print('   Value: ${nullableValue.toUpperCase()}');
    } else {
      print('   Value is null');
    }

    print('3. Null assertion (use carefully):');
    nullableValue = 'Hello';
    print('   Assured value: ${nullableValue!.length}'); // ! asserts non-null

    print('4. Safe late variable access:');
    initializeLateValue();
    print('   Late value: $lateValue');
  }

  void initializeLateValue() {
    if (!isInitialized) {
      lateValue = 'Initialized safely';
      isInitialized = true;
    }
  }
}

class DecisionGuideExample {
  void demonstrate() {
    print('When to use `late` vs nullable (`?`):');
    print('');

    // Scenario 1: Configuration that MUST be loaded
    ConfigService config = ConfigService();
    config.loadConfiguration();
    print('Config loaded: ${config.getApiUrl()}');

    // Scenario 2: Optional user settings
    UserSettings settings = UserSettings();
    settings.loadUserSettings();
    print('Theme: ${settings.getTheme()}');
    print('Language: ${settings.getLanguage()}');

    // Scenario 3: Widget with required initialization
    CustomWidget widget = CustomWidget();
    widget.initState();
    print('Widget ready: ${widget.isReady()}');
  }
}

// Use `late` when: Value will definitely be set before first use
class ConfigService {
  late String apiUrl;      // Required configuration
  late String appVersion;  // Always available
  late int maxRetries;     // Has default logic

  void loadConfiguration() {
    // These MUST be set - app can't function without them
    apiUrl = 'https://api.example.com';
    appVersion = '1.0.0';
    maxRetries = 3;
  }

  String getApiUrl() => apiUrl; // Safe to use directly
}

// Use nullable when: Value might legitimately be absent
class UserSettings {
  String? selectedTheme;    // User might not have chosen
  String? preferredLanguage; // Might use system default
  int? customTimeout;       // Might use app default

  void loadUserSettings() {
    // These might remain null - that's OK
    selectedTheme = null; // User hasn't chosen
    preferredLanguage = 'en'; // User specified
    customTimeout = null; // Use default
  }

  String getTheme() => selectedTheme ?? 'default';
  String getLanguage() => preferredLanguage ?? 'system-default';
}

// Use `late` for initialization patterns
class CustomWidget {
  late String id;
  late DateTime createdAt;
  String? title; // Optional title

  void initState() {
    // Called once during widget lifecycle
    id = 'widget_${DateTime.now().millisecondsSinceEpoch}';
    createdAt = DateTime.now();
    // title remains null unless set elsewhere
  }

  bool isReady() => true; // Can safely use id and createdAt
}

/*
DECISION GUIDE:

Use `late` when:
✅ Value will definitely be initialized before first use
✅ Initialization happens in constructor or init method
✅ You want to avoid null checks in your code
✅ The absence of the value indicates a programming error

Use nullable (`?`) when:
✅ Value might legitimately be absent/optional
✅ You need to handle the "no value" case gracefully  
✅ Value represents optional user input or configuration
✅ External APIs might not provide the value

ANTI-PATTERNS:
❌ Don't use `late` for values that might not be set
❌ Don't use nullable for values that are always required
❌ Don't use `!` (null assertion) unless you're certain
❌ Don't ignore nullable values without proper handling
*/

